(()=>{const b=document.body;if(!b?.classList.contains('editorial-2026'))return;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const q=['.home-eu-origin > *','.home-rd-section-heading','.home-rd-program','.home-impact-steps article','.home-rd-story > *','.home-one-section > *','.training-showcase-heading','.training-proof-strip article','.training-audience-grid article','.training-topic-grid article','.training-method-grid article','.training-gallery-grid figure','.training-feedback-section > *','.public-section > *','.online-course-cover > *'];const els=[...document.querySelectorAll(q.join(','))];els.forEach((el,i)=>{el.classList.add('ed-reveal');el.style.transitionDelay=`${Math.min((i%4)*45,135)}ms`});if(reduce){els.forEach(el=>el.classList.add('ed-visible'));return}const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('ed-visible');io.unobserve(e.target)}}),{threshold:.08,rootMargin:'0px 0px -7% 0px'});els.forEach(el=>io.observe(el));})();
